export interface InstanceArrays {
  bp1: ArrayLike<number>
  bp2: ArrayLike<number>
  y1: ArrayLike<number>
  y2: ArrayLike<number>
  colorType: ArrayLike<number>
}

export function packInstances(
  arrays: InstanceArrays,
  numInstances: number,
  buf: ArrayBuffer = new ArrayBuffer(numInstances * INSTANCE_STRIDE_BYTES),
) {
  const f32 = new Float32Array(buf)
  const u32 = new Uint32Array(buf)
  const { bp1, bp2, y1, y2, colorType } = arrays
  for (let i = 0; i < numInstances; i++) {
    const o = i * INSTANCE_STRIDE_WORDS
    u32[o + 0] = bp1[i]!
    u32[o + 1] = bp2[i]!
    f32[o + 2] = y1[i]!
    f32[o + 3] = y2[i]!
    f32[o + 4] = colorType[i]!
  }
  return buf
}

// Instance `i`'s `bp1`.
export function getInstanceBp1(u32: Uint32Array, i: number) {
  return u32[i * INSTANCE_STRIDE_WORDS]!
}

export function setInstanceBp1(u32: Uint32Array, i: number, v: number) {
  u32[i * INSTANCE_STRIDE_WORDS] = v
}

